  string fileA=Path.Combine(root,"Player A.mp3"),fileB=Path.Combine(root,"Player B.mp3");File.WriteAllBytes(fileA,new byte[]{1,2,3});File.WriteAllBytes(fileB,new byte[]{4,5,6});var audioDevice=new PlaybackTestDevice();
  using(var view=new MainView()){var controller=new Controller(view,Path.Combine(root,"player-backups"),new Playback(audioDevice));var a=new Song{Source=fileA,Artist="Interpret A",Title="Geladener Titel",Album="Thema A"};var b=new Song{Source=fileB,Artist="Interpret B",Title="Anderer Titel",Album="Thema B"};var project=new Project{Folders=new List<BoxFolder>{new BoxFolder{Name="000 Thema A",Theme="Thema A",Cover=themeImage,Songs=new List<Song>{a}},new BoxFolder{Name="001 Thema B",Theme="Thema B",Cover=singleImage,Songs=new List<Song>{b}}}};Call(controller,"ReplaceProject",project,null,true);view.OnlineCover.Checked=false;view.Show();Application.DoEvents();
   Check(!view.Player.Visible,"Player ist zunächst kompakt ausgeblendet");view.Songs.ContextMenuStrip.Items.OfType<ToolStripMenuItem>().First(item=>item.Text=="Im Player öffnen…").PerformClick();Application.DoEvents();Check(view.Player.Visible&&audioDevice.OpenCount==0&&view.Player.Caption.Text.Contains("Interpret A"),"Kontextmenü lädt ausgewählten Titel in Player ohne automatische Wiedergabe");
