 static object Call(object target,string name,params object[] args){return target.GetType().GetMethod(name,BindingFlags.Instance|BindingFlags.NonPublic).Invoke(target,args);}
 static Project Current(Controller c){return (Project)typeof(Controller).GetField("p",BindingFlags.Instance|BindingFlags.NonPublic).GetValue(c);}
 static ToolStripMenuItem Command(MainView view,string text){return view.Tools.Items.OfType<ToolStripDropDownButton>().SelectMany(menu=>menu.DropDownItems.OfType<ToolStripMenuItem>()).First(item=>item.Text==text);}
 static IEnumerable<Control> AllControls(Control root){foreach(Control child in root.Controls){yield return child;foreach(var nested in AllControls(child))yield return nested;}}
 static void SaveImage(Form form,string root,string name){Application.DoEvents();using(var image=new Bitmap(form.Width,form.Height)){using(var graphics=Graphics.FromImage(image))graphics.CopyFromScreen(form.Location,Point.Empty,image.Size);image.Save(Path.Combine(root,name));}}
}
